package com.coffeeshop.client.ui.home;

import android.app.Activity;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.text.InputFilter;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import com.google.android.material.bottomsheet.BottomSheetDialog;
import com.google.android.material.chip.Chip;
import com.google.android.material.chip.ChipGroup;
import com.coffeeshop.client.R;
import com.coffeeshop.client.catalog.model.Product;
import com.coffeeshop.client.data.OptionsConfig;
import com.coffeeshop.client.model.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/** Java/XML implementation of the product options modal sheet. */
public final class ProductOptionsSheet {
    public interface Listener { void onConfirm(SelectedOptions options,int quantity); }
    private static final Map<String,Draft> DRAFTS=new ConcurrentHashMap<>();
    private ProductOptionsSheet(){}
    private static final class Draft { Size size; SugarLevel sugar; IceLevel ice; Set<String> toppings=new LinkedHashSet<>(); boolean warm; String note=""; int quantity=1; }
    public static void show(Activity activity,Product product,CartItem editing,Listener listener){
        OptionsConfig config=OptionsConfig.forProduct(product); if(!config.hasOptions()) { listener.onConfirm(editing==null?config.defaults(activity):editing.options,editing==null?1:editing.quantity); return; }
        String draftKey=product.id+"_"+(editing==null?"new":editing.getLineKey()); Draft d=DRAFTS.get(draftKey);
        if(d==null){d=new Draft();d.size=editing==null?Size.S:editing.options.size;d.sugar=editing==null?SugarLevel.HUNDRED:editing.options.sugar;d.ice=editing==null?IceLevel.NORMAL:editing.options.ice;d.warm=editing!=null&&editing.options.warmUp;d.note=editing==null?"":editing.options.note;d.quantity=editing==null?1:editing.quantity;if(d.size==null)d.size=Size.S;if(d.sugar==null)d.sugar=SugarLevel.HUNDRED;if(d.ice==null)d.ice=IceLevel.NORMAL;if(editing!=null)for(Topping t:editing.options.toppings)d.toppings.add(t.id);DRAFTS.put(draftKey,d);}
        Draft draft=d; BottomSheetDialog dialog=new BottomSheetDialog(activity); LinearLayout root=column(activity); root.setBackground(roundBg(activity.getColor(R.color.coffee_surface),dp(activity,28),true));
        View handle=new View(activity);GradientDrawable hd=new GradientDrawable();hd.setColor(Color.rgb(202,190,178));hd.setCornerRadius(dp(activity,10));handle.setBackground(hd);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(dp(activity,40),dp(activity,4));hp.gravity=Gravity.CENTER;hp.topMargin=dp(activity,10);root.addView(handle,hp);
        ScrollView scroll=new ScrollView(activity);LinearLayout body=column(activity);body.setPadding(dp(activity,20),dp(activity,12),dp(activity,20),dp(activity,14));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout header=new LinearLayout(activity);header.setGravity(Gravity.CENTER_VERTICAL);ImageView image=new ImageView(activity);image.setImageResource(product.imageRes);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(roundBg(activity.getColor(R.color.coffee_cream),dp(activity,12),false));image.setClipToOutline(true);header.addView(image,new LinearLayout.LayoutParams(dp(activity,58),dp(activity,58)));
        LinearLayout titleCol=column(activity);titleCol.setPadding(dp(activity,12),0,0,0);TextView name=text(activity,product.name,17,true);titleCol.addView(name);TextView sub=text(activity,activity.getString(R.string.options_from_price,OptionsConfig.displayCategory(activity,product),money(activity,product.price)),13,false);titleCol.addView(sub);header.addView(titleCol,new LinearLayout.LayoutParams(0,-2,1));body.addView(header);
        final TextView[] buttonRef=new TextView[1];
        if(config.size){heading(activity,body,R.string.options_size);LinearLayout sizes=new LinearLayout(activity);sizes.setOrientation(LinearLayout.HORIZONTAL);body.addView(sizes);for(Size size:Size.values()){LinearLayout card=column(activity);card.setGravity(Gravity.CENTER);card.setPadding(dp(activity,3),dp(activity,8),dp(activity,3),dp(activity,8));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(activity,90),1);cp.setMarginEnd(dp(activity,7));sizes.addView(card,cp);TextView l=text(activity,size.label,19,true);TextView vol=text(activity,activity.getString(size==Size.S?R.string.options_volume_360:size==Size.M?R.string.options_volume_480:R.string.options_volume_600),12,false);TextView delta=text(activity,size==Size.S?activity.getString(R.string.options_default):activity.getString(R.string.options_size_delta,money(activity,size.priceDelta)),12,false);card.addView(l);card.addView(vol);card.addView(delta);styleSize(card,size==draft.size);card.setOnClickListener(v->{draft.size=size;for(int i=0;i<sizes.getChildCount();i++)styleSize(sizes.getChildAt(i),Size.values()[i]==size);refreshButton(buttonRef[0],activity,product,draft,editing);});}}
        if(config.sugar){heading(activity,body,R.string.options_sugar);ChipGroup sugar=chips(activity,body);SugarLevel[] levels=SugarLevel.values();for(SugarLevel level:levels){Chip c=chip(activity,sugar,sugarLabel(activity,level),false);c.setChecked(level==draft.sugar);sugar.addView(c);c.setOnClickListener(v->{draft.sugar=level;singleSelect(sugar,c);refreshButton(buttonRef[0],activity,product,draft,editing);});}}
        if(config.ice){heading(activity,body,R.string.options_ice);ChipGroup ice=chips(activity,body);IceLevel[] levels=IceLevel.values();for(IceLevel level:levels){Chip c=chip(activity,ice,iceLabel(activity,level),false);c.setChecked(level==draft.ice);ice.addView(c);c.setOnClickListener(v->{draft.ice=level;singleSelect(ice,c);refreshButton(buttonRef[0],activity,product,draft,editing);});}}
        if(!config.toppings.isEmpty()){heading(activity,body,R.string.options_toppings);TextView max=text(activity,activity.getString(R.string.options_max_toppings),12,false);max.setVisibility(draft.toppings.size()>=3?View.VISIBLE:View.GONE);body.addView(max);for(ToppingOption option:config.toppings){CheckBox box=new CheckBox(activity);box.setText(activity.getString(R.string.options_topping_price,activity.getString(option.nameRes),money(activity,option.price)));box.setTextColor(activity.getColor(R.color.coffee_text));box.setButtonTintList(android.content.res.ColorStateList.valueOf(activity.getColor(R.color.coffee_brown)));box.setChecked(draft.toppings.contains(option.id));body.addView(box);box.setOnCheckedChangeListener((b,checked)->{if(checked&&draft.toppings.size()<3)draft.toppings.add(option.id);else if(!checked)draft.toppings.remove(option.id);else b.setChecked(false);max.setVisibility(draft.toppings.size()>=3?View.VISIBLE:View.GONE);for(int i=0;i<body.getChildCount();i++)if(body.getChildAt(i) instanceof CheckBox){CheckBox other=(CheckBox)body.getChildAt(i);other.setEnabled(other.isChecked()||draft.toppings.size()<3);}refreshButton(buttonRef[0],activity,product,draft,editing);});}}
        if(config.warm){Switch warm=new Switch(activity);warm.setText(R.string.options_warm);warm.setTextColor(activity.getColor(R.color.coffee_text));warm.setChecked(draft.warm);body.addView(warm);warm.setOnCheckedChangeListener((b,checked)->{draft.warm=checked;refreshButton(buttonRef[0],activity,product,draft,editing);});}
        TextView noteHeading=text(activity,activity.getString(R.string.options_note),14,true);LinearLayout.LayoutParams nh=new LinearLayout.LayoutParams(-1,-2);nh.topMargin=dp(activity,12);body.addView(noteHeading,nh);EditText note=new EditText(activity);note.setSingleLine(true);note.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});note.setHint(R.string.options_note_hint);note.setText(draft.note);note.setBackgroundResource(R.drawable.bg_input);note.setPadding(dp(activity,12),0,dp(activity,12),0);body.addView(note,new LinearLayout.LayoutParams(-1,dp(activity,48)));note.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){draft.note=s.toString();}public void afterTextChanged(android.text.Editable e){}});
        LinearLayout footer=new LinearLayout(activity);footer.setGravity(Gravity.CENTER_VERTICAL);footer.setPadding(dp(activity,18),dp(activity,10),dp(activity,18),dp(activity,14));footer.setBackgroundColor(activity.getColor(R.color.coffee_surface));TextView minus=text(activity,"−",20,true),qty=text(activity,String.valueOf(draft.quantity),16,true),plus=text(activity,"+",20,true);for(TextView v:new TextView[]{minus,qty,plus}){v.setGravity(Gravity.CENTER);v.setTextColor(activity.getColor(R.color.coffee_brown));}footer.addView(minus,new LinearLayout.LayoutParams(dp(activity,42),dp(activity,44)));footer.addView(qty,new LinearLayout.LayoutParams(dp(activity,30),dp(activity,44)));footer.addView(plus,new LinearLayout.LayoutParams(dp(activity,42),dp(activity,44)));Button add=new Button(activity);add.setAllCaps(false);add.setTextColor(activity.getColor(R.color.coffee_surface));add.setBackgroundResource(R.drawable.bg_primary_button);footer.addView(add,new LinearLayout.LayoutParams(0,dp(activity,50),1));root.addView(footer);buttonRef[0]=add;
        minus.setOnClickListener(v->{if(draft.quantity>1)draft.quantity--;qty.setText(String.valueOf(draft.quantity));refreshButton(add,activity,product,draft,editing);});plus.setOnClickListener(v->{if(draft.quantity<20)draft.quantity++;qty.setText(String.valueOf(draft.quantity));refreshButton(add,activity,product,draft,editing);});refreshButton(add,activity,product,draft,editing);
        add.setOnClickListener(v->{List<Topping> toppings=OptionsConfig.toppings(product,draft.toppings,activity);SelectedOptions selected=new SelectedOptions(config.size?draft.size:null,config.sugar?draft.sugar:null,config.ice?draft.ice:null,toppings,draft.warm,draft.note);listener.onConfirm(selected,draft.quantity);DRAFTS.remove(draftKey);dialog.dismiss();});
        int maxHeight=Math.min(dp(activity,650),activity.getResources().getDisplayMetrics().heightPixels-dp(activity,56));root.setLayoutParams(new android.view.ViewGroup.LayoutParams(-1,maxHeight));dialog.setContentView(root);dialog.show();
    }
    private static void refreshButton(TextView b,Activity a,Product p,Draft d,CartItem old){if(b==null)return;int total=p.price+(d.size==null?0:d.size.priceDelta);OptionsConfig c=OptionsConfig.forProduct(p);for(ToppingOption t:c.toppings)if(d.toppings.contains(t.id))total+=t.price;total*=d.quantity;b.setText(a.getString(old==null?R.string.options_add_to_cart:R.string.options_update,money(a,total)));}
    private static void singleSelect(ChipGroup g,Chip selected){for(int i=0;i<g.getChildCount();i++)((Chip)g.getChildAt(i)).setChecked(g.getChildAt(i)==selected);}
    private static ChipGroup chips(Activity a,LinearLayout parent){HorizontalScrollView scroll=new HorizontalScrollView(a);scroll.setHorizontalScrollBarEnabled(false);ChipGroup g=new ChipGroup(a);g.setSingleLine(true);scroll.addView(g);parent.addView(scroll);return g;}
    private static Chip chip(Activity a,ChipGroup g,String label,boolean check){Chip c=new Chip(a);c.setText(label);c.setCheckable(true);c.setChecked(check);c.setChipBackgroundColorResource(R.color.coffee_cream);c.setTextColor(a.getColor(R.color.coffee_brown));return c;}
    private static void styleSize(View v,boolean selected){GradientDrawable b=roundBg(selected?0xFFE9DCCB:0xFFFFFCF8,dp(v.getContext(),12),false);b.setStroke(dp(v.getContext(),selected?2:1),selected?v.getContext().getColor(R.color.coffee_brown):v.getContext().getColor(R.color.coffee_border));v.setBackground(b);}
    private static void heading(Activity a,LinearLayout parent,int res){TextView t=text(a,a.getString(res),15,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(a,14);p.bottomMargin=dp(a,5);parent.addView(t,p);}
    private static LinearLayout column(Activity a){LinearLayout l=new LinearLayout(a);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private static TextView text(Activity a,String s,int size,boolean bold){TextView t=new TextView(a);t.setText(s);t.setTextSize(size);t.setTextColor(a.getColor(R.color.coffee_text));if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    private static GradientDrawable roundBg(int color,int radius,boolean topOnly){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadii(topOnly?new float[]{radius,radius,radius,radius,0,0,0,0}:new float[]{radius,radius,radius,radius,radius,radius,radius,radius});return d;}
    private static int dp(Activity a,int n){return Math.round(n*a.getResources().getDisplayMetrics().density);}
    private static int dp(android.content.Context a,int n){return Math.round(n*a.getResources().getDisplayMetrics().density);}
    private static String money(Activity a,int n){return a.getString(R.string.money_vnd,NumberFormat.getIntegerInstance(new Locale("vi","VN")).format(n));}
    private static String sugarLabel(Activity a,SugarLevel s){switch(s){case ZERO:return a.getString(R.string.options_sugar_0);case THIRTY:return a.getString(R.string.options_sugar_30);case FIFTY:return a.getString(R.string.options_sugar_50);case SEVENTY:return a.getString(R.string.options_sugar_70);default:return a.getString(R.string.options_sugar_100);}}
    private static String iceLabel(Activity a,IceLevel i){switch(i){case NONE:return a.getString(R.string.options_ice_none);case LESS:return a.getString(R.string.options_ice_less);case MORE:return a.getString(R.string.options_ice_more);default:return a.getString(R.string.options_ice_normal);}}
}
